import {TILES,SHOWS,newGame,player,command,targets,adjacent} from './engine.js';
import {icon} from './icons.js';
import {SERVER_URL} from './config.js';
import {api, BandConnection, credential} from './network.js';
const $=s=>document.querySelector(s),app=$('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,d=null)=>{try{return JSON.parse(localStorage.getItem(k))??d;}catch{return d;}};
const save=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));}catch{}};
let game=null,myId=null,mode=null,view='game',selected=null,rewardAction='add',connection=null,online=[],connected=false,busy=false,networkReady=false,animating=false,frames=[],generation=0;
let name=read('encore.name',''),sound=read('encore.sound',false),session=read('encore.session'),audioCtx;
let invite=new URL(location.href).searchParams.get('band')?.toUpperCase()||'';
const endpoint=(SERVER_URL||location.origin).replace(/\/$/,'');
const rnd=()=>crypto.getRandomValues(new Uint32Array(1))[0];
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function beep(i=0){if(!sound)return;try{audioCtx??=new AudioContext();audioCtx.resume();const o=audioCtx.createOscillator(),v=audioCtx.createGain();o.type='square';o.frequency.value=[196,247,294,392,494,587,784,988,1175][i%9];v.gain.setValueAtTime(.022,audioCtx.currentTime);v.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+.13);o.connect(v).connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+.14);}catch{}}
function me(){return game?.players.find(p=>p.id===myId);}
function header(){return `<header class="masthead"><a href="${esc(location.pathname)}" class="wordmark" aria-label="ENCORE! accueil">ENCORE<span>!</span></a><div class="mast-meta">LA TOURNÉE PIRATE<br><span>VOL. 01 / GUITARE & GRANDES GUEULES</span></div><button class="sound small" data-action="sound" aria-label="${sound?'Couper':'Activer'} le son" aria-pressed="${sound}">${icon('sound')}<span>${sound?'ON':'OFF'}</span></button></header>`;}
function screen(){const s=SHOWS[game?.show||0];return `<div class="show-label"><span>SHOW <b>${String((game?.show||0)+1).padStart(2,'0')}</b><small>/ 03</small></span><strong>${esc(s.name)}</strong><span class="live">● LIVE</span></div><div class="lcd"><img src="./stage.png" alt="Un chansonnier punk joue devant la foule dans un sous-sol, en pixels verts"><div class="lcd-caption"><span>${game?esc(s.crowd):'UNE GUITARE. UN MICRO. TOUT À GAGNER.'}</span><span>${mode==='multi'?'COOP 2P':'CH. 01'}</span></div></div>`;}
function shell(content){return `${header()}<section class="console"><div class="hardware"><span>PORTABLE BAND SYSTEM</span><b>REC <i></i></b></div>${screen()}${content}<div class="console-bottom"><span>DIY AUDIO / NO REFUNDS</span><span class="vents">▰ ▰ ▰ ▰ ▰</span></div></section><footer class="page-footer"><span>ENCORE! <b>PROTOTYPE 0.2</b></span><button data-action="rules">COMMENT ÇA JOUE?</button></footer><dialog id="details"></dialog>`;}
function home(){return `<section class="home"><div class="tape">ON JOUE MÊME SI ÇA GRÉSILLE.</div><h1>Ton premier show<br>commence ici.</h1><p>Pige tes tuiles. Branche les synergies.<br>Fais lever la salle en cinq manches.</p><div class="demo-combo"><div>${icon('mic')}<b>×2</b></div><span>+</span><div class="combo-main">${icon('guitar')}<b>×4</b></div><span>+</span><div>${icon('mic')}<b>×2</b></div></div><p class="combo-caption">Voix + guitare : ça s’amplifie des deux côtés.</p><label class="field">TON NOM DE SCÈNE<input id="name" maxlength="20" value="${esc(name)}" placeholder="Ex. Simon" autocomplete="nickname"></label><button class="primary" data-action="solo">${icon('bolt')} PARTIR EN SOLO ${icon('arrow')}</button>${read('encore.solo')?'<button class="secondary" data-action="resume">REPRENDRE MA TOURNÉE SOLO</button>':''}<div class="multi-start"><button class="secondary" data-action="create" ${!networkReady||busy?'disabled':''}>CRÉER UN BAND</button><button class="secondary" data-action="join" ${!networkReady||busy?'disabled':''}>REJOINDRE</button></div><label class="field code-field">CODE DU BAND<input id="code" maxlength="12" value="${esc(invite)}" placeholder="12 caractères" spellcheck="false" autocomplete="off"></label><p class="network-note">${networkReady?'Deux musiciens, un lien. Aucun compte nécessaire.':'Aperçu solo disponible. Connexion au serveur multijoueur indisponible. Réessaie dans un instant.'}</p>${session&&networkReady?'<button class="text-button" data-action="reconnect">REPRENDRE MON BAND</button>':''}</section>`;}
function meters(){const t=targets(game);return `<div class="meters">${[['q','QUALITÉ','star'],['e','ÉNERGIE','bolt']].map(([key,label,ic])=>`<div class="meter">${icon(ic)}<div><div class="meter-label">${label}<b>${game[key]}<span> / ${t[key]}</span></b></div><div class="meter-track" role="progressbar" aria-label="${label}" aria-valuemin="0" aria-valuemax="${t[key]}" aria-valuenow="${Math.min(game[key],t[key])}"><i style="width:${Math.min(100,game[key]/t[key]*100)}%"></i></div></div></div>`).join('')}</div>`;}
function tileButton(t,index,extra=''){const empty=!t||t.kind==='empty',d=empty?{name:'Case vide',icon:'empty'}:TILES[t.kind];const lit=!empty&&!t.inactive&&t.m>1;return `<button class="tile ${empty?'empty':''} ${t?.inactive?'inactive':''} ${lit?'lit':''} ${extra}" data-action="tile" data-index="${index}" aria-label="${esc(d.name)}${lit?`, multiplicateur ${t.m}`:''}" style="--i:${index}">${t?.level?`<span class="level">+${t.level}</span>`:''}${icon(d.icon)}<span class="tile-name">${esc(d.name)}</span>${t?.charges?`<span class="charge">${t.charges} CH.</span>`:''}${lit?`<span class="mult">×${t.m}</span>`:''}${t?.inactive?'<span class="dead">HORS SERVICE</span>':''}${t?.after?'<span class="after">'+esc(t.after)+'</span>':''}${t?.q||t?.e||t?.f?`<span class="tile-points">${t.q?`${t.q} Q `:''}${t.e?`${t.e} É `:''}${t.f?`${t.f} F`:''}${t.repeats?` · ×${1+t.repeats}`:''}</span>`:''}</button>`;}
function grid(){const p=me(),b=p?.board.length?p.board:Array(9).fill(null);const links=[];b.forEach((t,i)=>t?.links?.forEach(j=>{if(j>i||!b[j]?.links?.includes(i)){const x=i%3*100+50,y=Math.floor(i/3)*100+50;links.push(`<line x1="${x}" y1="${y}" x2="${j%3*100+50}" y2="${Math.floor(j/3)*100+50}"/>`);}}));return `<div class="grid-wrap"><div class="grid ${animating?'playing':''}">${b.map((t,i)=>tileButton(t,i)).join('')}</div><svg class="connections" viewBox="0 0 300 300" aria-hidden="true">${links.join('')}</svg></div>`;}
function players(){return `<div class="bandmates">${game.players.map(p=>`<div class="bandmate ${p.id===myId?'you':''}"><div class="portrait">${icon('user')}</div><div><strong>${esc(p.name)} ${p.id===myId?'<small>TOI</small>':''}</strong><span>${p.q} Q · ${p.e} É · ${p.fans} FANS</span><small>${mode==='multi'&&!online.includes(p.id)?'Déconnecté · partie conservée':p.ready?'Prêt pour la manche':p.rewarded?'Récompense choisie':'Guitariste chansonnier'}</small></div></div>`).join('')}</div>`;}
function gameView(){const p=me();if(!p)return '<p>Connexion au band…</p>';return `${meters()}<div class="grid-heading"><span>TON SET ${icon('guitar')}</span><span>${p.last?`DERNIÈRE PIGE : +${p.last.q} Q / +${p.last.e} É`:'BRANCHE TES SYNERGIES'}</span></div>${grid()}<div class="readout" aria-live="polite">${animating?'ÇA MONTE…':p.last?`+${p.last.f} fans directs · Touche une tuile pour comprendre son effet.`:'Les 9 tuiles seront pigées et placées au hasard.'}</div>${players()}<div class="controls"><div class="round">MANCHE <b>${game.round}</b><span>/ ${SHOWS[game.show].rounds}</span></div><button class="inventory" data-action="inventory">${icon('bag')} INVENTAIRE · ${p.inventory.length}</button></div>${phaseAction()}<div class="session-line"><span>${mode==='multi'?`${connected?'CONNECTÉ':'RECONNEXION…'} · ${esc(session?.code)}`:'SOLO · SAUVEGARDE AUTOMATIQUE'}</span><button data-action="quit">QUITTER</button></div>`;}
function phaseAction(){const p=me();if(game.phase==='lobby')return `<div class="lobby"><h2>${game.players.length===2?'Le band est là.':'La balance est prête.'}</h2><p>${mode==='multi'?'Partage le lien avant de lancer la tournée.':'Trois salles. Un inventaire. À toi de jouer.'}</p>${mode==='multi'?'<button class="secondary" data-action="invite">COPIER LE LIEN D’INVITATION</button>':''}${game.players[0].id===myId?`<button class="primary" data-action="start" ${busy||mode==='multi'&&!connected?'disabled':''}>LANCER LA TOURNÉE ${icon('arrow')}</button>`:'<p>Le créateur lance la tournée.</p>'}</div>`;
 if(game.phase==='show')return `<button class="primary play" data-action="ready" ${busy||animating||p.ready||mode==='multi'&&!connected?'disabled':''}>${icon('bolt')}${p.ready?'EN ATTENTE DU BAND…':game.round?'ENVOYER LA MANCHE SUIVANTE':'FAIRE DU BRUIT'}${icon('arrow')}</button>`;
 if(game.phase==='reward')return `<div class="result"><span class="tape">SHOW RÉUSSI</span><h2>La salle en redemande.</h2><p>+${p.showFans} fans de performance, en plus des fans gagnés par tes tuiles.</p><button class="primary" data-action="rewards" ${animating||p.rewarded?'disabled':''}>${p.rewarded?'TON BAND CHOISIT ENCORE…':'PASSER EN COULISSES'} ${icon('arrow')}</button></div>`;
 return `<div class="result"><span class="tape">${game.phase==='won'?'TOURNÉE BOUCLÉE!':'ON A CONNU MEILLEUR.'}</span><h2>${game.phase==='won'?'Ils étaient deux.<br>Ils sont '+p.fans+'.':'Le show s’arrête ici.'}</h2><p>${game.phase==='won'?'Le toit tremble encore. On remet ça?':'Il fallait atteindre les deux objectifs. Ton prochain set sera meilleur.'}</p><div class="tour-results">${game.history.map(h=>`<span>${h.won?'✓':'×'} ${SHOWS[h.show].name} · ${h.q} Q / ${h.e} É</span>`).join('')}</div><button class="primary" data-action="again">NOUVELLE TOURNÉE ${icon('repeat')}</button></div>`;}
function inventoryView(){const p=me();const available=p.inventory.filter(t=>!t.exhausted).length;return `<section class="inventory-screen"><button class="back" data-action="back">← RETOUR AU SHOW</button><div class="section-title"><h1>Ton inventaire<span>.</span></h1><b>${p.inventory.length} TUILES</b></div><p>${available} disponibles · ${p.inventory.length-available} épuisées<br>9 pigées par manche. Charges et états sont remis à zéro au prochain show.</p><div class="inventory-list">${p.inventory.map((t,i)=>`<button class="inventory-item ${t.exhausted?'exhausted':''}" data-action="inspect-inventory" data-index="${i}"><span class="item-icon">${icon(TILES[t.kind].icon)}</span><span><strong>${esc(TILES[t.kind].name)}${t.level?' +'+t.level:''}</strong><small>${esc(TILES[t.kind].build)} · ${t.exhausted?'Épuisée':t.inactive?'Désactivée':t.charges?t.charges+' charges':'Disponible'}</small></span>${icon('arrow')}</button>`).join('')||'<p>Inventaire vide : la grille sera remplie de cases vides.</p>'}</div><details><summary>LE CATALOGUE · ${Object.keys(TILES).length} SORTES</summary><div class="catalog">${Object.entries(TILES).map(([k,d])=>`<div><strong>${esc(d.name)}</strong><p>${esc(d.text)}</p></div>`).join('')}</div></details></section>`;}
function rewardsView(){const p=me();return `<section class="reward-screen"><button class="back" data-action="back">← REVOIR LE SHOW</button><span class="tape">LES COULISSES / SHOW ${game.show+1}</span><h1>Un petit ajustement.<br>Un gros prochain show.</h1><p>Choisis une seule action. Chaque membre choisit pour son inventaire.</p><div class="reward-tabs">${[['add','AJOUTER'],['upgrade','AMÉLIORER'],['remove','RETIRER']].map(([k,label])=>`<button class="${rewardAction===k?'active':''}" data-action="reward-tab" data-kind="${k}">${label}</button>`).join('')}</div>${p.rewarded?'<p>Choix enregistré. En attente du band…</p>':rewardAction==='add'?`<div class="reward-cards">${p.offers.map(k=>`<button class="reward-card" data-action="choose-add" data-kind="${k}" ${busy?'disabled':''}><span class="item-icon">${icon(TILES[k].icon)}</span><small>${esc(TILES[k].build)}</small><strong>${esc(TILES[k].name)}</strong><p>${esc(TILES[k].text)}</p><span class="choose">AJOUTER AU SET +</span></button>`).join('')}</div>`:`<p>${rewardAction==='upgrade'?'+1 qualité pour une Guitare, +1 fan pour le Canard, +1 énergie pour les autres. Permanent pour la tournée, maximum +3.':'Retire définitivement une tuile de ton inventaire. Les autres ressortiront plus souvent.'}</p><div class="inventory-list">${p.inventory.map(t=>`<button class="inventory-item" data-action="choose-${rewardAction}" data-id="${esc(t.id)}" ${busy||rewardAction==='upgrade'&&t.level>=3?'disabled':''}><span class="item-icon">${icon(TILES[t.kind].icon)}</span><span><strong>${esc(TILES[t.kind].name)}</strong><small>Niveau +${t.level}</small></span><b>${rewardAction==='upgrade'?'+1':'−'}</b></button>`).join('')}</div>`}</section>`;}
function render(){if(view==='rewards'&&game?.phase!=='reward')view='game';app.innerHTML=shell(!game?home():view==='inventory'?inventoryView():view==='rewards'?rewardsView():gameView());}
function inspect(t){const empty=!t||t.kind==='empty',d=empty?{name:'Case vide',text:'Ajoutée à la pige si moins de 9 tuiles sont disponibles, puis mélangée aux autres cases. Elle ne rejoint pas l’inventaire.',icon:'empty',build:'Grille'}:TILES[t.kind];const dlg=$('#details');dlg.innerHTML=`<button class="dialog-close" data-action="close" aria-label="Fermer">${icon('close')}</button><div class="detail-icon">${icon(d.icon)}</div><small>${esc(d.build)}</small><h2>${esc(d.name)}</h2><p>${esc(d.text)}</p>${t?.inactive?'<p class="warning">Désactivée : aucun effet, aucune synergie normale. Occupe toujours une case.</p>':''}${t?.exhausted?'<p>Épuisée : ne sera plus pigée avant le prochain show.</p>':''}${t?.level?'<p>Amélioration permanente : +'+t.level+' à sa production de base.</p>':''}${t?.charges?'<p>'+t.charges+' charges. Réinitialisées au prochain show.</p>':''}${t?.m?`<div class="detail-score"><span>BASE ${t.q/t.m} Q · ${t.e/t.m} É · ${t.f/t.m} F</span><b>×${t.m}${t.repeats?' · '+t.repeats+' redéclenchement(s)':''}</b><span>PRODUCTION ${t.q*(1+(t.repeats||0))} Q · ${t.e*(1+(t.repeats||0))} É · ${t.f*(1+(t.repeats||0))} F</span></div>`:''}<button class="secondary" data-action="close">COMPRIS</button>`;dlg.showModal();}
function rules(){const dlg=$('#details');dlg.innerHTML=`<button class="dialog-close" data-action="close" aria-label="Fermer">${icon('close')}</button><span class="tape">LA BALANCE</span><h2>Fais lever la salle.</h2><ol><li>À chaque manche, 9 tuiles sont pigées dans ton inventaire et placées au hasard.</li><li>Les synergies touchent les quatre côtés, jamais les diagonales. Une Guitare entre deux Voix vaut ×4 ; chaque Voix vaut ×2.</li><li>Les charges s’activent, puis les bonus, les multiplicateurs et les points. Tout se résout automatiquement.</li><li>Atteins la qualité <strong>et</strong> l’énergie demandées en 5 manches maximum.</li><li>Entre les shows, ajoute, améliore ou retire une tuile. En coop, les points s’additionnent et chacun garde son inventaire.</li></ol><p>Épuisée : sortie du show. Désactivée : encore pigée, sans effet. Ces états et les charges se réinitialisent au show suivant. Les améliorations et les fans restent.</p><button class="primary" data-action="close">C’EST PARTI</button>`;dlg.showModal();}
function animate(){frames.forEach(clearTimeout);animating=true;render();for(let i=0;i<9;i++)frames.push(setTimeout(()=>beep(i),i*90));frames.push(setTimeout(()=>{animating=false;render();},1100));}
function accept(g){const previous=game;game=g;busy=false;if(mode==='solo')save('encore.solo',{game,myId});if(previous&&g.round>previous.round&&g.show===previous.show)animate();else render();}
function receive(data){
 if(mode!=='multi')return;
 const changed=JSON.stringify(online)!==JSON.stringify(data.online)||!connected;
 myId=data.id;online=data.online;connected=true;
 if(data.game&&(!game||data.game.revision>game.revision)){const pending=busy;accept(data.game);busy=pending;}
 else if(changed)render();
}
async function send(type,extra={}){
 if(busy||!game)return;
 const msg={type,revision:game.revision,show:game.show,round:game.round,...extra};
 if(mode==='solo'){try{accept(command(game,myId,msg,rnd()));}catch(e){toast(e.message);}return;}
 if(!connection||!connected){toast('Connexion en cours. Ta partie est conservée.');return;}
 busy=true;render();const current=connection;
 try{const data=await current.send(msg);if(current===connection)receive(data);}
 catch(e){if(current===connection)toast(e.message);}
 finally{if(current===connection){busy=false;render();current.sync();}}
}
function getName(){name=$('#name')?.value.trim()||name||'Sans nom';save('encore.name',name);return name;}
function clearNetwork(){generation++;connection?.close();connection=null;connected=false;busy=false;}
function solo(){getName();clearNetwork();mode='solo';myId='solo';game=newGame();game.players=[player(myId,name)];view='game';save('encore.solo',{game,myId});render();}
async function connect(code,newSession=false){
 getName();clearNetwork();game=null;myId=null;online=[];mode='multi';view='game';
 if(newSession||!session||session.code!==code){session={code,token:credential(),name};save('encore.session',session);}
 const gen=generation;busy=true;render();
 connection=new BandConnection(endpoint,session,{
  state:data=>{if(gen!==generation)return;if(!game)busy=false;receive(data);},
  status:ok=>{if(gen!==generation)return;connected=ok;render();},
  error:error=>{if(gen!==generation)return;busy=false;toast(error.message);if(!game){clearNetwork();mode=null;}render();},
  revision:()=>game?.revision
 });
 await connection.open();
}
app.addEventListener('input',e=>{if(e.target.id==='name'){name=e.target.value;save('encore.name',name);}if(e.target.id==='code')invite=e.target.value.toUpperCase();});
app.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;
 if(a==='sound'){sound=!sound;save('encore.sound',sound);beep();render();}
 if(a==='rules')rules();if(a==='close')$('#details').close();
 if(a==='solo')solo();if(a==='resume'){const s=read('encore.solo');if(s?.game?.version===1){clearNetwork();mode='solo';myId=s.myId;game=s.game;view='game';render();}else toast('Sauvegarde incompatible. Lance une nouvelle tournée.');}
 if(a==='start'||a==='ready')send(a);
 if(a==='inventory'){view='inventory';render();}
 if(a==='back'){view='game';render();}
 if(a==='rewards'){view='rewards';rewardAction='add';render();}
 if(a==='reward-tab'){rewardAction=b.dataset.kind;render();}
 if(a==='choose-add')send('reward',{action:'add',kind:b.dataset.kind});
 if(a==='choose-upgrade')send('reward',{action:'upgrade',tileId:b.dataset.id});
 if(a==='choose-remove'){selected=b.dataset.id;const t=me().inventory.find(t=>t.id===selected);const dlg=$('#details');dlg.innerHTML=`<h2>Retirer ${esc(TILES[t.kind].name)}?</h2><p>Cette tuile quitte ton inventaire pour le reste de la tournée. C’est ton unique récompense pour ce show.</p><button class="primary" data-action="confirm-remove">RETIRER LA TUILE</button><button class="secondary" data-action="close">GARDER</button>`;dlg.showModal();}
 if(a==='confirm-remove'){$('#details').close();send('reward',{action:'remove',tileId:selected});}
 if(a==='tile')inspect(me()?.board[Number(b.dataset.index)]);
 if(a==='inspect-inventory')inspect(me().inventory[Number(b.dataset.index)]);
 if(a==='quit'||a==='again'){clearNetwork();frames.forEach(clearTimeout);animating=false;game=null;mode=null;view='game';render();}
 if(a==='create'){
  getName();busy=true;render();const token=credential();
  try{const d=await api(endpoint,'create',token,{name});session={code:d.code,token,name};save('encore.session',session);await connect(d.code);}
  catch(e){busy=false;toast(e.message);render();}
 }
 if(a==='join'){const code=($('#code')?.value||invite).trim().toUpperCase();if(!/^[A-F0-9]{12}$/.test(code)){toast('Entre les 12 caractères du code d’invitation.');return;}await connect(code);}
 if(a==='reconnect'&&session)await connect(session.code);
 if(a==='invite'){const u=new URL(location.href);u.search='';u.searchParams.set('band',session.code);try{await navigator.clipboard.writeText(u.href);toast('Lien copié. Envoie-le à ton band!');}catch{toast('Copie ce code : '+session.code);}}
});
render();
async function checkServer(){
 try{const r=await fetch(endpoint+'/health',{signal:AbortSignal.timeout(12000)});const d=await r.json();const ready=!!(r.ok&&d.ok&&d.protocol===2);if(ready!==networkReady){networkReady=ready;if(!game)render();}}
 catch{}
 if(!networkReady)setTimeout(checkServer,15000);
}
checkServer();
window.addEventListener('online',()=>connection?.sync());
window.addEventListener('visibilitychange',()=>{if(!document.hidden)connection?.sync();});
